int snd_timer_user_select(struct file *file, struct snd_timer_select __user *_tselect)
{
    struct snd_timer_user *u = file->private_data;
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    int err;

    if (u->timer) {
        snd_timer_free(u->timer);
        u->timer = NULL;
    }

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    timer = snd_timer_new(&tselect.card, tselect.id, &tselect.ticks);
    if (!timer)
        return -ENOMEM;

    u->timer = timer;

    if (snd_timer_system_register(timer, NULL) < 0) {
        snd_timer_free(timer);
        u->timer = NULL;
        return -EINVAL;
    }

    timer->callback = snd_timer_user_callback;
    timer->private_data = u;
    timer->flags |= SNDRV_TIMER_FLG_FAST;

    return 0;
}

int snd_timer_select(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer *timer;
    int err;

    if (!file->private_data)
        return -EFAULT;

    if (file->private_data) {
        snd_timer_close(file);
    }

    timer = kzalloc(sizeof(*timer), GFP_KERNEL);
    if (!timer)
        return -ENOMEM;

    if (copy_from_user(&timer->select, _tselect, sizeof(timer->select))) {
        kfree(timer);
        return -EFAULT;
    }

    timer->queues = kzalloc(timer->select.queues * sizeof(struct snd_timer_queue), GFP_KERNEL);
    if (!timer->queues) {
        kfree(timer);
        return -ENOMEM;
    }

    timer->file = file;
    timer->fast = 1;

    snd_timer_setup_callbacks(timer);

    file->private_data = timer;

    return 0;
}

int snd_timer_user_select(struct file *file, struct snd_timer_select __user *_tselect)
{
    struct snd_timer_user *timer;
    struct snd_timer_select tselect;
    int err;

    timer = file->private_data;
    if (!timer)
        return -EFAULT;

    if (timer->timer) {
        snd_timer_free(timer->timer);
        timer->timer = NULL;
    }

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    timer->timer = snd_timer_new(&tselect);
    if (!timer->timer)
        return -ENOMEM;

    timer->treadq = kmalloc(sizeof(*timer->treadq), GFP_KERNEL);
    if (!timer->treadq) {
        snd_timer_free(timer->timer);
        timer->timer = NULL;
        return -ENOMEM;
    }

    timer->twriteq = kmalloc(sizeof(*timer->twriteq), GFP_KERNEL);
    if (!timer->twriteq) {
        kfree(timer->treadq);
        snd_timer_free(timer->timer);
        timer->timer = NULL;
        return -ENOMEM;
    }

    snd_timer_set_callback(timer->timer, &snd_timer_user_ops, timer);
    timer->timer->flags |= SNDRV_TIMER_FLG_FAST;

    return 0;
}

int snd_timer_user_select(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer_user *tusr = file->private_data;
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    struct snd_timer_id tid;
    int err;

    if (tusr->timer) {
        snd_timer_close(tusr->timer);
        tusr->timer = NULL;
    }

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    tid = tselect.tid;

    timer = snd_timer_new(&tid, "user", 0);
    if (!timer)
        return -ENOMEM;

    tusr->timer = timer;
    tusr->queue = kmalloc(sizeof(*tusr->queue), GFP_KERNEL);
    if (!tusr->queue) {
        snd_timer_close(timer);
        tusr->timer = NULL;
        return -ENOMEM;
    }

    tusr->queue->timer = timer;
    tusr->queue->file = file;
    tusr->queue->running = 0;
    tusr->queue->size = 0;
    tusr->queue->fill = 0;
    tusr->queue->data = NULL;

    timer->callback = snd_timer_user_callback;
    timer->private_free = snd_timer_user_free;
    timer->private_data = tusr;

    timer->flags |= SNDRV_TIMER_FLG_FAST;

    return 0;
}
